configuration.jsScript:
// Phan loai originator:
// - device: telemetry tu thiet bi → chay automation conditions
// - bulk_command: app gui lenh truc tiep qua Asset telemetry API
//   (POST /api/plugins/telemetry/ASSET/{homeAssetId}/timeseries/ANY
//    voi body { "bulk_command": { mode, command, params, ... } })
if (metadata.originatorType === 'ASSET') {
    if (msg.bulk_command !== undefined && msg.bulk_command !== null) {
        return ['bulk_command'];
    }
    return ['asset_other'];
}
return ['device'];

// Gom tat ca actions tu tat ca triggered rules thanh queue.
// Lay action[0] lam msg hien tai, luu phan con lai vao metadata.pendingActions.
var allActions = [];
for (var i = 0; i < msg.triggeredRules.length; i++) {
    var rule = msg.triggeredRules[i];
    if (!rule.actions) continue;
    for (var j = 0; j < rule.actions.length; j++) {
        var src = rule.actions[j];
        allActions.push({
            type:           src.type,
            device_id:      src.device_id,
            device_name:    src.device_name,
            device_ids:     src.device_ids,
            room_asset_id:  src.room_asset_id,
            home_asset_id:  src.home_asset_id,
            filter_type:    src.filter_type,
            command:        src.command,
            params:         src.params,
            message:        src.message,
            seconds:        src.seconds,
            _ruleId:        rule.ruleId,
            _ruleName:      rule.ruleName
        });
    }
}
if (allActions.length === 0) {
    return {msg: {}, metadata: metadata, msgType: 'NO_MORE_ACTIONS'};
}
var newMeta = metadata;
newMeta.triggerDeviceId   = String(msg.triggerDeviceId || '');
newMeta.triggerDeviceName = String(msg.triggerDeviceName || '');
newMeta.triggerTimestamp  = String(msg.timestamp || new Date().getTime());
var first = allActions.splice(0, 1)[0];
newMeta.pendingActions = JSON.stringify(allActions);
newMeta.actionRuleId   = first._ruleId;
newMeta.actionRuleName = first._ruleName;
return {msg: first, metadata: newMeta, msgType: 'EXECUTE_ACTION'};

// Route action toi node xu ly tuong ung.
// device_command (1 device) va bulk_command (nhieu devices) deu di qua
// Normalize to Bulk Format → SmartHomeBulkCommandNode.
switch (msg.type) {
    case 'device_command':    return ['bulk_command'];
    case 'bulk_command':      return ['bulk_command'];
    case 'send_notification': return ['notification'];
    case 'delay':             return ['delay'];
    default:                  return ['unknown'];
}

// Chuyen device_command (1 device) hoac bulk_command (nhieu devices)
// ve cung 1 format ma SmartHomeBulkCommandNode chap nhan.
//
// Input device_command: { type, device_id, command, params }
// → Output: { mode: 'device_list', device_ids: [device_id], command, params }
//
// Input bulk_command: { type, mode, room_asset_id|home_asset_id|device_ids, command, params, filter_type }
// → Output: giu nguyen (bo truong 'type' va '_rule*')
var out;
if (msg.type === 'device_command') {
    out = {
        mode:       'device_list',
        device_ids: [msg.device_id],
        command:    msg.command,
        params:     msg.params || {}
    };
} else {
    out = {
        mode:           msg.mode || 'device_list',
        device_ids:     msg.device_ids,
        room_asset_id:  msg.room_asset_id,
        home_asset_id:  msg.home_asset_id,
        command:        msg.command,
        params:         msg.params || {},
        filter_type:    msg.filter_type || null
    };
}
var newMeta = metadata;
newMeta.actionRuleId   = msg._ruleId   || metadata.actionRuleId;
newMeta.actionRuleName = msg._ruleName || metadata.actionRuleName;
return {msg: out, metadata: newMeta, msgType: 'BULK_COMMAND'};

configuration.alarmDetailsBuildJs:
var d = {};
d.message  = msg.message  || 'Automation triggered';
d.ruleName = msg._ruleName || '';
return d;

configuration.jsScript:
// Pop action tiep theo tu queue.
// Neu con action → EXECUTE_ACTION → loop lai Action Type Router.
// Neu het → NO_MORE_ACTIONS → ket thuc (di toi Build Log).
var pending = JSON.parse(metadata.pendingActions || '[]');
if (pending.length === 0) {
    return {msg: msg, metadata: metadata, msgType: 'NO_MORE_ACTIONS'};
}
var next = pending.splice(0, 1)[0];
var newMeta = metadata;
newMeta.pendingActions = JSON.stringify(pending);
newMeta.actionRuleId   = next._ruleId   || metadata.actionRuleId;
newMeta.actionRuleName = next._ruleName || metadata.actionRuleName;
return {msg: next, metadata: newMeta, msgType: 'EXECUTE_ACTION'};

// Tao ban ghi log luu vao telemetry key 'automation_log' tren Home Asset.
// msg o day la ket qua cua action cuoi cung (bulk command result hoac noop khi het action).
var log = {
    automation_log: JSON.stringify({
        rule_id:        metadata.actionRuleId    || 'direct',
        rule_name:      metadata.actionRuleName  || 'direct_command',
        triggered_at:   new Date().toISOString(),
        trigger_device: metadata.triggerDeviceName || metadata.triggerDeviceId || 'app',
        status:         'success',
        total:          msg.totalDevices   || 0,
        success_count:  msg.successCount   || 0,
        failed_count:   msg.failedCount    || 0
    })
};
return {msg: log, metadata: metadata, msgType: 'POST_TELEMETRY_REQUEST'};

// Log loi: tu SmartHomeConditionNode 'Failure' hoac SmartHomeBulkCommandNode 'Failure'.
var log = {
    automation_log: JSON.stringify({
        rule_id:        metadata.actionRuleId   || 'unknown',
        rule_name:      metadata.actionRuleName || 'unknown',
        triggered_at:   new Date().toISOString(),
        trigger_device: metadata.triggerDeviceName || metadata.triggerDeviceId || 'app',
        status:         'failed',
        total:          msg.totalDevices  || 0,
        success_count:  msg.successCount  || 0,
        failed_count:   msg.failedCount   || 0,
        error:          msg.error         || 'condition_evaluation_failed',
        results:        msg.results       || []
    })
};
return {msg: log, metadata: metadata, msgType: 'POST_TELEMETRY_REQUEST'};

// App gui direct bulk command qua Asset telemetry API:
// POST /api/plugins/telemetry/ASSET/{homeAssetId}/timeseries/ANY
// Body: { "bulk_command": { mode, room_asset_id|home_asset_id|device_ids, command, params, filter_type } }
//
// Unwrap msg.bulk_command ra, set metadata trigger = app, pendingActions = [] (khong co them action sau).
var bc = msg.bulk_command;
var out = {
    mode:           bc.mode          || 'device_list',
    device_ids:     bc.device_ids,
    room_asset_id:  bc.room_asset_id,
    home_asset_id:  bc.home_asset_id,
    command:        bc.command,
    params:         bc.params        || {},
    filter_type:    bc.filter_type   || null
};
var newMeta = metadata;
newMeta.triggerDeviceName = 'app';
newMeta.triggerDeviceId   = metadata.originatorId || 'app';
newMeta.triggerTimestamp  = String(new Date().getTime());
newMeta.actionRuleId      = 'direct';
newMeta.actionRuleName    = 'app_direct_command';
newMeta.pendingActions    = '[]';
return {msg: out, metadata: newMeta, msgType: 'BULK_COMMAND'};
